const questDefs=[['tap100','터치 트레이닝','톡톡 탐험가',100,2,150,s=>s.taps],['tap1000','연타 챌린지','연타의 달인',1000,2,2000,s=>s.taps],['buy10','간식 수집가','간식 단골',10,1.6,300,s=>s.counts.reduce((a,b)=>a+b,0)],['level5','성장의 기록','든든한 친구',5,1.4,800,s=>level(s)],['fever5','피버 챌린지','피버 마스터',5,1.8,1800,s=>s.fevers]];
function questTier(a,s=state){return s.questTiers?.[a.id]||0}
function questGoal(a,s=state){return Math.min(MAX,Math.ceil(a.base*a.growth**questTier(a,s)))}
function questReward(a){return Math.min(MAX,Math.ceil(a.reward*1.8**questTier(a)))}
const achievements=questDefs.map(([id,name,title,base,growth,reward,metric])=>({id,name,title,base,growth,reward,metric,test:s=>metric(s)>=questGoal({id,base,growth},s),progress:s=>format(metric(s))+' / '+format(questGoal({id,base,growth},s))}));
const oldThresholds=[0,40,160,450,1100,2500,5500,12000,26000,55000,115000,240000];
const fresh=()=>({version:4,unlocked:items.map((_,i)=>i===0),questTiers:{},points:0,total:0,counts:items.map(()=>0),sound:true,taps:0,fevers:0,claimed:[],title:'말랑말랑 새싹',selectedPhoto:0,autoPhoto:true,highestLevel:1,lastSaved:Date.now()});
const nonnegative=(v,fallback=0)=>Number.isFinite(v)&&v>=0?Math.min(v,MAX):fallback;
function load(){let raw;try{raw=JSON.parse(localStorage.getItem(SAVE_KEY))}catch{};if(!raw||typeof raw!=='object')return fresh();const s=fresh();s.points=nonnegative(raw.points);s.total=Math.max(s.points,nonnegative(raw.total));if(Array.isArray(raw.counts))s.counts=items.map((_,i)=>Math.floor(nonnegative(raw.counts[i])));s.unlocked=items.map((_,i)=>i===0||s.counts[i]>0||raw.unlocked?.[i]===true);s.questTiers=Object.fromEntries(achievements.map(a=>[a.id,Math.floor(nonnegative(raw.questTiers?.[a.id],raw.claimed?.includes(a.id)?1:0))]));s.sound=typeof raw.sound==='boolean'?raw.sound:true;s.taps=Math.floor(nonnegative(raw.taps));s.fevers=Math.floor(nonnegative(raw.fevers));s.claimed=Array.isArray(raw.claimed)?raw.claimed.filter(id=>achievements.some(a=>a.id===id)):[];s.title=typeof raw.title==='string'?raw.title:s.title;s.selectedPhoto=Math.min(31,Math.floor(nonnegative(raw.selectedPhoto)));s.autoPhoto=raw.autoPhoto!==false;s.lastSaved=nonnegative(raw.lastSaved,Date.now());let previous=1;if(!raw.version||raw.version<2){oldThresholds.forEach((t,i)=>{if(s.total>=t)previous=i+1})}if(raw.version===3){let oldLevel=1;while(oldLevel<300&&s.total>=100*Math.pow(1.75,oldLevel-1))oldLevel++;previous=Math.max(previous,oldLevel)}s.highestLevel=Math.max(previous,Math.min(300,Math.floor(nonnegative(raw.highestLevel,1))));return s}
let state=load(), feverUntil=0, snackUntil=0, nextSnack=Date.now()+randomDelay(), audio, toastTimer, saveTimer, lastFrame=performance.now(), bounceEnergy=0, lastDraw='', lastFeverSeconds=-1;
function randomDelay(){return 90000}
function threshold(l){return Math.min(MAX,350*Math.pow(1.95,l-1))}
function level(s=state){let l=Math.max(1,s.highestLevel||1);while(l<300&&s.total>=threshold(l))l++;return l}
function nextThreshold(l){return threshold(l)}
function format(n){if(!Number.isFinite(n))return '∞';n=Math.max(0,Math.floor(n));const units=['','만','억','조','경','해','자','양','구','간','정','재','극'];if(n<10000)return String(n);const income=typeof state==='undefined'?1:Math.max(power('click'),power('auto'),1);const low=Math.max(0,Math.floor(Math.log10(income)/4));const top=Math.min(units.length-1,Math.floor(Math.log10(n)/4));const floor=Math.min(low,Math.max(0,top-1));let parts=[];for(let i=top;i>=floor;i--){const v=Math.floor(n/Math.pow(10000,i))%10000;if(v)parts.push(v+units[i])}return parts.join(' ')||'0'}
const plus=(a,b)=>Math.min(MAX,a+b);
function power(type){return items.reduce((sum,x,i)=>plus(sum,x.type===type?Math.min(MAX,x.power*state.counts[i]*Math.pow(2,Math.floor(state.counts[i]/10))):0),type==='click'?1:0)}
function unlockCost(i){return Math.min(MAX,items[i].base*12)}
function cost(i){return Math.min(MAX,Math.ceil(items[i].base*Math.pow(1.42,state.counts[i])))}
function save(){if(!saveTimer)saveTimer=setTimeout(()=>{saveTimer=null;saveNow()},250)}
function saveNow(){state.lastSaved=Date.now();try{localStorage.setItem(SAVE_KEY,JSON.stringify(state))}catch{toast('기록을 저장하지 못했어. 브라우저 저장 공간을 확인해줘.')}}
window.addEventListener('pagehide',saveNow);
let awayAt=state.lastSaved;
function applyAway(){const elapsed=Math.min(OFFLINE_CAP,Math.max(0,(Date.now()-awayAt)/1000));if(elapsed>2&&power('auto')>0){const amount=Math.min(MAX,power('auto')*Math.floor(elapsed));gain(amount,false);toast('자리 비운 동안 +'+format(amount)+'원 획득!')}awayAt=Date.now()}
document.addEventListener('visibilitychange',()=>{if(document.hidden){awayAt=Date.now();saveNow()}else{applyAway();tick=Date.now();lastFrame=performance.now()}});
function toast(message){const e=$('toast');e.textContent=message;e.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>e.classList.remove('show'),2800)}
const portraitFiles=["3588.jpg", "227.jpg", "153.jpg", "6415.jpg", "579.jpg", "6480.webp", "6481.webp", "3085.jpg", "4486.jpg", "3452.jpg", "4485.jpg", "187.jpg", "3063.jpg", "596.jpg", "598.jpg", "3086.jpg", "3090.jpg", "5545.jpg", "6933.jpg", "5839.jpg", "5555.jpg", "6508.jpg", "4390.jpg", "3080.webp", "5538.jpg", "6878.jpg", "6486.jpg", "6935.jpg", "7010.jpg", "6812.jpg", "3324.png", "6353.jpg"];
const photo=new Image();photo.onload=()=>{$('photoError').classList.add('hidden');drawPhoto(true)};photo.onerror=()=>$('photoError').classList.remove('hidden');let loadedPortrait=-1;function loadPhoto(){loadedPortrait=state.selectedPhoto;photo.src='portraits/'+portraitFiles[state.selectedPhoto]} $('retryPhoto').onclick=loadPhoto;loadPhoto();
let visualGrowth=0;
function growthTarget(){return Math.min(.30,.012*(level()-1)+.20*(1-Math.exp(-state.taps/300)))}
function drawPhoto(force=false){if(!photo.complete||!photo.naturalWidth)return;const l=level();if(state.autoPhoto)state.selectedPhoto=(l-1)%portraitFiles.length;if(loadedPortrait!==state.selectedPhoto){loadPhoto();return}const key=state.selectedPhoto+':'+visualGrowth.toFixed(4);if(!force&&lastDraw===key)return;lastDraw=key;const c=$('photo'),ctx=c.getContext('2d'),crop=({"3588.jpg":[.25,.16,.75,.80],"227.jpg":[.04,.08,.92,.92],"153.jpg":[0,.1,1,.9],"6415.jpg":[.36,0,.64,1],"6486.jpg":[0,.05,1,.84],"6878.jpg":[0,.06,1,.83],"7010.jpg":[.05,.10,.90,.78]})[portraitFiles[state.selectedPhoto]]||[0,0,1,1],sw=photo.width*crop[2],sh=photo.height*crop[3],w=c.width,h=c.height,sx=photo.width*crop[0],cy=photo.height*crop[1];ctx.clearRect(0,0,w,h);ctx.fillStyle='#101d30';ctx.fillRect(0,0,w,h);const ratio=Math.min(w/sw,h/sh),dw=sw*ratio,dh=sh*ratio,dx=(w-dw)/2,dy=(h-dh)/2;for(let y=0;y<h;y+=4){const t=Math.max(0,Math.min(1,(y/h-.30)/.45)),smooth=t*t*(3-2*t),spread=visualGrowth*smooth;if(y<dy||y>=dy+dh)continue;const sy=(y-dy)/ratio;const edge=dw*.24,outer=edge*(1-spread),middle=dw-2*outer;ctx.drawImage(photo,sx,sy+cy,sw*.24,Math.min(sh-sy,4/ratio),dx,y,outer,4);ctx.drawImage(photo,sx+sw*.24,sy+cy,sw*.52,Math.min(sh-sy,4/ratio),dx+outer,y,middle,4);ctx.drawImage(photo,sx+sw*.76,sy+cy,sw*.24,Math.min(sh-sy,4/ratio),dx+outer+middle,y,outer,4)}$('growthHint').textContent='몸집 성장 '+Math.round(visualGrowth*100)+'% · 터치할수록 쑥쑥!'}
function beep(){if(!state.sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();if(audio.state==='suspended')audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.frequency.setValueAtTime(520,audio.currentTime);o.frequency.exponentialRampToValueAtTime(290,audio.currentTime+.065);g.gain.setValueAtTime(.025,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.08);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+.08)}catch{}}
function celebrate(){const scene=$('scene'),b=document.createElement('div');b.className='levelburst';b.innerHTML='<strong>LEVEL UP!</strong><small>LV. '+level()+' · 우진이가 성장했어!</small>';scene.append(b);setTimeout(()=>b.remove(),1800);if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;for(let i=0;i<24;i++){const p=document.createElement('i');p.className='confetti';p.style.setProperty('--color',['#ffce55','#ff8156','#fff7db','#89bc89'][i%4]);p.style.setProperty('--x',(Math.random()-.5)*550+'px');p.style.setProperty('--y',(Math.random()-.5)*650+'px');scene.append(p);setTimeout(()=>p.remove(),1400)}}
function gain(n,animate=true){const old=level();state.points=plus(state.points,n);state.total=plus(state.total,n);const current=level();if(current>old){state.highestLevel=current;if(animate)celebrate()}render();save()}
function tap(x,y){const amount=power('click')*(Date.now()<feverUntil?2:1);state.taps++;gain(amount);beep();bounceEnergy=Math.min(1,bounceEnergy+.38);const f=document.createElement('span'),r=$('scene').getBoundingClientRect();f.className='float';f.textContent='+'+format(amount)+'원';f.style.setProperty('--tilt',(Math.random()*16-8)+'deg');f.style.left=Math.max(8,Math.min(r.width-65,x-r.left))+'px';f.style.top=(y-r.top)+'px';$('scene').append(f);setTimeout(()=>f.remove(),900)}
$('character').addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&e.button!==0)return;e.preventDefault();tap(e.clientX,e.clientY)});$('character').addEventListener('click',e=>{if(e.detail===0){const r=$('character').getBoundingClientRect();tap(r.left+r.width/2,r.top+r.height*.6)}});$('character').addEventListener('contextmenu',e=>e.preventDefault());
$('upgrades').innerHTML=items.map((x,i)=>`<button class="upgrade" id="upgrade${i}" data-i="${i}"><span class="uicon">${x.icon}</span><span class="utext"><strong>${x.name}</strong><small>${x.desc}</small></span><span class="cost"></span></button>`).join('');
