function render(){const l=level();if(state.autoPhoto)state.selectedPhoto=(l-1)%portraitFiles.length;const prev=l===1?0:threshold(l-1),next=nextThreshold(l),cash=$('points');cash.textContent=format(state.points);$('level').textContent='LV. '+l;$('rank').textContent=state.title;$('clickstat').textContent='+'+format(power('click'))+'원';$('autostat').textContent=format(power('auto'))+'원 / 초';$('perclick').textContent='터치당 +'+format(power('click'))+'원 · 누적 '+format(state.total)+'원';$('next').textContent=l>=300?'최고 레벨 달성!':'다음 레벨까지';$('progressText').textContent=l>=300?'MAX LEVEL':format(Math.max(0,state.total-prev))+' / '+format(next-prev)+'원';$('fill').style.width=l>=300?'100%':Math.max(0,Math.min(100,(state.total-prev)/(next-prev)*100))+'%';$('sound').textContent=state.sound?'♪':'♩';$('sound').setAttribute('aria-pressed',String(state.sound));drawPhoto();$('photoTabs').querySelectorAll('button').forEach((b,i)=>{b.disabled=l<i+1;b.textContent=b.disabled?'🔒 LV.'+(i+1):'LV.'+(i+1);b.classList.toggle('selected',i===state.selectedPhoto);b.setAttribute('aria-pressed',String(i===state.selectedPhoto))});items.forEach((x,i)=>{const b=$('upgrade'+i);const locked=!state.unlocked[i],price=locked?unlockCost(i):cost(i);b.disabled=state.points<price||l<items[i].unlock;b.classList.toggle('locked-snack',locked);b.querySelector('.utext small').textContent=locked?'잠금 해제 후 구매 가능 · '+items[i].desc:items[i].desc;b.querySelector('.cost').innerHTML=l<items[i].unlock?'🔒 LV.'+items[i].unlock+'<small>해금 '+format(unlockCost(i))+'원</small>':locked?'🔓 잠금 해제<small>'+format(price)+'원</small>':'업그레이드<small>'+format(price)+'원 · 보유 '+state.counts[i].toLocaleString('ko-KR')+'</small>'});achievements.forEach((a,i)=>{const claimed=false,done=a.test(state),b=$('achButton'+i);$('achInfo'+i).textContent='단계 '+(questTier(a)+1)+' · '+a.progress(state)+' · 보상 '+format(questReward(a))+'원';b.textContent=claimed?'완료':done?'받기':'진행 중';b.disabled=claimed||!done});const titles=['말랑말랑 새싹',...achievements.filter(a=>state.claimed.includes(a.id)).map(a=>a.title)];if(!titles.includes(state.title))state.title=titles[0];const select=$('titleSelect');if(select.dataset.options!==titles.join('|')){select.innerHTML=titles.map(t=>`<option value="${t}">${t}</option>`).join('');select.dataset.options=titles.join('|')}select.value=state.title;$('shopWallet').textContent=format(state.points)+'원';$('autoRate').textContent='초당 +'+format(power('auto'))+'원';$('autoPhoto').setAttribute('aria-pressed',String(state.autoPhoto))}
$('upgrades').onclick=e=>{const b=e.target.closest('button');if(!b)return;const i=+b.dataset.i;if(!Number.isInteger(i)||!items[i]||level()<items[i].unlock)return;const locked=!state.unlocked[i],price=locked?unlockCost(i):cost(i);if(state.points<price)return;state.points-=price;if(locked){state.unlocked[i]=true;toast(items[i].name+' 잠금 해제! 이제 업그레이드할 수 있어.')}else{state.counts[i]++;toast(items[i].name+' 업그레이드! '+items[i].desc)}beep();b.classList.remove('purchase-pop');void b.offsetWidth;b.classList.add('purchase-pop');render();save()};
$('autoPhoto').onclick=()=>{state.autoPhoto=true;render();save();toast('레벨에 맞춰 사진이 자동으로 바뀌어!')};
$('photoTabs').onclick=e=>{const b=e.target.closest('button');if(!b||b.disabled)return;state.selectedPhoto=+b.dataset.photo;state.autoPhoto=false;render();save()};
$('achievements').onclick=e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const a=achievements.find(x=>x.id===b.dataset.ach);if(!a||!a.test(state))return;const reward=questReward(a);state.questTiers[a.id]=questTier(a)+1;if(!state.claimed.includes(a.id))state.claimed.push(a.id);state.title=a.title;gain(reward);toast('칭호 획득: '+a.title)};
