function frame(now){const dt=Math.min(.05,(now-lastFrame)/1000);lastFrame=now;const target=growthTarget();if(Math.abs(target-visualGrowth)>.0001){visualGrowth+=(target-visualGrowth)*Math.min(1,dt*10);drawPhoto()}if(bounceEnergy>.001){bounceEnergy*=Math.exp(-10*dt);const motion=matchMedia('(prefers-reduced-motion: reduce)').matches?0:bounceEnergy;$('photo').style.transform=`translateY(${-5*motion}px) scale(${1+.018*motion},${1-.012*motion})`}else $('photo').style.transform='';requestAnimationFrame(frame)}requestAnimationFrame(frame);
